class Solution {
public:
    string longestPalindrome(string s) {
        int n = s.size();
        if (n == 0) return "";
        vector<int> d1(n);
        int l = 0, r = -1;
        for (int i = 0; i < n; ++i) {
            int k = (i > r) ? 1 : min(d1[l + r - i], r - i + 1);
            while (i - k >= 0 && i + k < n && s[i - k] == s[i + k]) ++k;
            d1[i] = k;
            if (i + k - 1 > r) {
                l = i - k + 1;
                r = i + k - 1;
            }
        }

        vector<int> d2(n);
        l = 0; r = -1;
        for (int i = 0; i < n; ++i) {
            int k = (i > r) ? 0 : min(d2[l + r - i + 1], r - i + 1);
            while (i - k - 1 >= 0 && i + k < n && s[i - k - 1] == s[i + k]) ++k;
            d2[i] = k;
            if (i + k - 1 > r) {
                l = i - k;
                r = i + k - 1;
            }
        }

        int bestLen = 0, bestStart = 0;
        for (int i = 0; i < n; ++i) {
            int len1 = 2 * d1[i] - 1;
            if (len1 > bestLen) {
                bestLen = len1;
                bestStart = i - d1[i] + 1;
            }
            int len2 = 2 * d2[i];
            if (len2 > bestLen) {
                bestLen = len2;
                bestStart = i - d2[i];
            }
        }
        return s.substr(bestStart, bestLen);
    }
};
